import json
from collections import defaultdict
from datetime import datetime

# Read and parse CSV
with open('/home/ping/workspace/qwen/cashbook_record_20260801_210634.csv', 'rb') as f:
    raw = f.read()

text = raw.decode('gb18030')
lines = text.split('\n')

# Find data lines (skip header/notes)
data_lines = []
header_found = False
for line in lines:
    if line.startswith('记录时间'):
        header_found = True
        continue
    if header_found and line.strip():
        data_lines.append(line.strip())

# Parse
records = []
for line in data_lines:
    parts = line.split(',')
    if len(parts) < 5:
        continue
    try:
        dt = datetime.strptime(parts[0], '%Y-%m-%d %H:%M:%S')
        category = parts[1]
        flow_type = parts[2]
        amount = float(parts[3])
        note = parts[4]
        account = parts[5] if len(parts) > 5 else ''
        records.append({
            'date': dt,
            'category': category,
            'type': flow_type,
            'amount': amount,
            'note': note,
            'account': account
        })
    except:
        continue

print(f"Total records: {len(records)}")
print(f"Date range: {min(r['date'] for r in records).strftime('%Y-%m-%d')} ~ {max(r['date'] for r in records).strftime('%Y-%m-%d')}")

# Analysis
total_income = sum(r['amount'] for r in records if r['type'] == '收入')
total_expense = sum(r['amount'] for r in records if r['type'] == '支出')

# By category
cat_expense = defaultdict(float)
cat_income = defaultdict(float)
for r in records:
    if r['type'] == '支出':
        cat_expense[r['category']] += r['amount']
    else:
        cat_income[r['category']] += r['amount']

# By month
month_expense = defaultdict(float)
month_income = defaultdict(float)
for r in records:
    m = r['date'].strftime('%Y-%m')
    if r['type'] == '支出':
        month_expense[m] += r['amount']
    else:
        month_income[m] += r['amount']

# By day of week
dow_names = ['周一','周二','周三','周四','周五','周六','周日']
dow_expense = defaultdict(float)
dow_count = defaultdict(int)
for r in records:
    if r['type'] == '支出':
        dow = r['date'].weekday()
        dow_expense[dow] += r['amount']
        dow_count[dow] += 1

# Top expenses
top_expenses = sorted(records, key=lambda x: x['amount'], reverse=True)[:20]

